_DURATION_RE = re.compile(
    r"(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?"
)
_UNIT_SECONDS = (24 * 60 * 60, 60 * 60, 60, 1)


def parse_duration(s):
    """Convert a duration string such as '1h30m' to an integer number of seconds."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    text = s.strip()
    if not text:
        raise ValueError("empty duration")

    match = _DURATION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid duration: {s!r}")

    total = 0
    for amount, seconds_per_unit in zip(match.groups(), _UNIT_SECONDS):
        if amount is not None:
            total += int(amount) * seconds_per_unit
    return total
